package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import android.media.session.*;import android.media.Rating;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.*;import java.lang.reflect.*;import java.util.*;import java.security.*;import java.time.Duration;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class Notification167Test {
 Context c;NotificationManager nm;
 @Before public void setup()throws Exception{c=RuntimeEnvironment.getApplication();c.getSharedPreferences("profile",0).edit().putString("id","123").commit();Provider p=new Provider("VolnaSyntheticKeyStore",1.0,"test only"){};p.put("KeyStore.AndroidKeyStore",WarmWriterTest.MemoryStore.class.getName());Security.insertProviderAt(p,1);Session.put(c,"OAuth SYNTHETIC_167_TOKEN_12345","SYNTHETIC_167_CLIENT_12345");nm=c.getSystemService(NotificationManager.class);nm.cancelAll();FakeLikeService.reset();Library lib=new Library(c);lib.upsert(track("1",false));lib.upsert(track("2",true));lib.save();PlaybackCheckpoint.save(c,Arrays.asList("sc:1","sc:2"),0,12000,false,false,false,false,true,false);}
 @After public void cleanup(){PlaybackService.instance=null;ResidentChecks.resetForTest();Security.removeProvider("VolnaSyntheticKeyStore");}
 Library.Track track(String id,boolean liked)throws Exception{Library.Track t=LibraryUi163Test.song(id,"Track "+id);t.liked=liked;return t;}
 void set(Object obj,String name,Object value)throws Exception{Field f=PlaybackService.class.getDeclaredField(name);f.setAccessible(true);f.set(obj,value);}
 Object get(Object obj,String name)throws Exception{Field f=PlaybackService.class.getDeclaredField(name);f.setAccessible(true);return f.get(obj);}
 ServiceController<PlaybackService> player()throws Exception{ServiceController<PlaybackService> ctrl=Robolectric.buildService(PlaybackService.class).create();PlaybackService s=ctrl.get();s.current="sc:1";set(s,"queue",new ArrayList<>(Arrays.asList("sc:1","sc:2")));set(s,"activeTrack",track("1",false));set(s,"pendingPosition",12000L);s.startForeground(7,PlaybackNotice.playing(s,track("1",false),false,false,false,"",null));return ctrl;}
 @Test public void pauseKeepsServiceAndNotificationBeyondOldThirtySeconds()throws Exception{ServiceController<PlaybackService> ctrl=player();try{PlaybackService s=ctrl.get();s.pause();long savedAt=PlaybackCheckpoint.read(c).savedAt;Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(40));assertEquals(savedAt,PlaybackCheckpoint.read(c).savedAt);assertFalse(Shadows.shadowOf(s).isStoppedBySelf());assertSame(s,PlaybackService.instance);assertNotNull(Shadows.shadowOf(nm).getNotification(7));assertEquals("sc:1",s.current);assertEquals(2,((List<?>)get(s,"queue")).size());for(Field f:PlaybackService.class.getDeclaredFields())assertNotEquals("idleRelease",f.getName());}finally{ctrl.destroy();}}
 @Test public void pausedTaskRemovalDoesNotStopOrClearQueue()throws Exception{ServiceController<PlaybackService> ctrl=player();try{ctrl.get().pause();ctrl.get().onTaskRemoved(new Intent());assertFalse(Shadows.shadowOf(ctrl.get()).isStoppedBySelf());assertEquals(Arrays.asList("sc:1","sc:2"),PlaybackCheckpoint.read(c).queue);assertNotNull(Shadows.shadowOf(nm).getNotification(7));}finally{ctrl.destroy();}}
 @Test public void explicitCloseStopsAndDoesNotResurrectCard()throws Exception{ServiceController<PlaybackService> ctrl=player();ctrl.get().stopForLocalChange();assertTrue(Shadows.shadowOf(ctrl.get()).isStoppedBySelf());assertNull(PlaybackCheckpoint.read(c));assertNull(Shadows.shadowOf(nm).getNotification(7));ctrl.destroy();assertNull(Shadows.shadowOf(nm).getNotification(7));}
 @Test public void destroyedPlayerDoesNotCreateSeparatePausedCard()throws Exception{ServiceController<PlaybackService> ctrl=player();ctrl.get().pause();ctrl.destroy();assertNull(Shadows.shadowOf(nm).getNotification(7));assertNull(PlaybackService.instance);assertNotNull(PlaybackCheckpoint.read(c));}
 @Test public void liveNotificationHasHeartAndExplicitClose()throws Exception{Notification n=PlaybackNotice.playing(c,track("1",false),true,true,false,"",null);assertEquals(5,n.actions.length);assertEquals("В любимое",n.actions[3].title);assertEquals("Убрать плеер",n.actions[4].title);assertEquals(R.drawable.ic_heart_outline,n.actions[3].getIcon().getResId());}
 @Test public void localFileDoesNotGetCloudLike()throws Exception{Library.Track local=new Library.Track("file:///test.wav","Local","Test",2000,false);Notification n=PlaybackNotice.playing(c,local,false,false,false,"",null);assertEquals(4,n.actions.length);for(Notification.Action a:n.actions)assertFalse("В любимое".contentEquals(a.title));}
 @Test public void notificationCapturesTargetAndDesiredState()throws Exception{PendingIntent old=NotificationLikeService.pending(c,track("1",false),true);PendingIntent unlike=NotificationLikeService.pending(c,track("1",true),false);PendingIntent other=NotificationLikeService.pending(c,track("2",true),false);assertNotEquals(old,unlike);assertNotEquals(old,other);Intent command=Shadows.shadowOf(old).getSavedIntent();assertEquals("1",command.getStringExtra("track"));assertEquals("123",command.getStringExtra("owner"));assertTrue(command.getBooleanExtra("liked",false));}
 @Test public void mediaSessionExposesHeartCustomActionAndRating()throws Exception{ServiceController<PlaybackService> ctrl=player();try{ctrl.get().likeConfirmed("123","1",true);Library.Track selected=(Library.Track)get(ctrl.get(),"activeTrack");android.media.session.PlaybackState state=PlaybackNotice.state(selected,false,false,false,12000);assertEquals(PlaybackNotice.LIKE_ACTION,state.getCustomActions().get(0).getAction());assertEquals("Убрать лайк",state.getCustomActions().get(0).getName());assertTrue((state.getActions()&android.media.session.PlaybackState.ACTION_SET_RATING)!=0);assertTrue(PlaybackNotice.metadata(selected,180000).getRating(android.media.MediaMetadata.METADATA_KEY_USER_RATING).hasHeart());}finally{ctrl.destroy();}}
 @Test public void confirmationOfOldTrackDoesNotChangeNewTrackHeart()throws Exception{ServiceController<PlaybackService> ctrl=player();try{ctrl.get().current="sc:2";set(ctrl.get(),"activeTrack",track("2",true));ctrl.get().likeConfirmed("123","1",false);assertTrue(((Library.Track)get(ctrl.get(),"activeTrack")).liked);}finally{ctrl.destroy();}}
 @Test public void closeReceiverIgnoresStaleAccount()throws Exception{seedNotice();new PlaybackNoticeReceiver().onReceive(c,new Intent("CLOSE").putExtra("owner","999"));assertNotNull(PlaybackCheckpoint.read(c));assertNotNull(Shadows.shadowOf(nm).getNotification(7));new PlaybackNoticeReceiver().onReceive(c,new Intent("CLOSE").putExtra("owner","123"));assertNull(PlaybackCheckpoint.read(c));assertNull(Shadows.shadowOf(nm).getNotification(7));}
 public static class FakeLikeService extends NotificationLikeService {static AccountWriter.Callback callback;static int submits,closes;static String op,id;static boolean accepted=true;static void reset(){callback=null;submits=closes=0;op=id="";accepted=true;}@Override protected AccountWriter createWriter(AccountWriter.Callback cb){callback=cb;return new AccountWriter(getApplicationContext(),cb){public boolean submit(String operation,String track,String list,String title){submits++;op=operation;id=track;return accepted;}public void close(){closes++;super.close();}};}}
 void seedNotice()throws Exception{nm.notify(7,PlaybackNotice.playing(c,track("1",false),false,false,false,"",null));}
 ServiceController<FakeLikeService> like(boolean desired)throws Exception{seedNotice();ServiceController<FakeLikeService> ctrl=Robolectric.buildService(FakeLikeService.class).create();ctrl.get().onStartCommand(NotificationLikeService.command(c,track("1",false),desired),0,1);return ctrl;}
 void confirmed(){FakeLikeService.callback.complete(new Intent().putExtra("owner","123").putExtra("track","1").putExtra("op",FakeLikeService.op));}
 @Test public void heartChangesOnlyAfterServerConfirmation()throws Exception{ServiceController<FakeLikeService> ctrl=like(true);try{assertEquals("LIKE",FakeLikeService.op);assertFalse(new Library(c).find("sc:1").liked);assertEquals("В любимое",Shadows.shadowOf(nm).getNotification(7).actions[3].title);assertNotNull(Shadows.shadowOf(nm).getNotification(9));confirmed();assertTrue(new Library(c).find("sc:1").liked);assertNull(Shadows.shadowOf(nm).getNotification(7));assertNull(Shadows.shadowOf(nm).getNotification(9));assertTrue(Shadows.shadowOf(ctrl.get()).isStoppedBySelf());assertEquals(1,FakeLikeService.closes);}finally{ctrl.destroy();}}
 @Test public void unlikeIsExplicitAndServerConfirmed()throws Exception{Library lib=new Library(c);lib.find("sc:1").liked=true;lib.save();ServiceController<FakeLikeService> ctrl=like(false);try{assertEquals("UNLIKE",FakeLikeService.op);assertTrue(new Library(c).find("sc:1").liked);confirmed();assertFalse(new Library(c).find("sc:1").liked);}finally{ctrl.destroy();}}
 @Test public void forbiddenDoesNotFakeSuccessOrRemovePlaybackCard()throws Exception{ServiceController<FakeLikeService> ctrl=like(true);FakeLikeService.callback.failed(403,"HTTP",false);assertFalse(new Library(c).find("sc:1").liked);assertNotNull(Shadows.shadowOf(nm).getNotification(7));assertTrue(Shadows.shadowOf(nm).getNotification(9).extras.getCharSequence(Notification.EXTRA_TEXT).toString().contains("403"));ctrl.destroy();assertNotNull(Shadows.shadowOf(nm).getNotification(7));}
 @Test public void unknownResultIsNotRetriedAutomatically()throws Exception{ServiceController<FakeLikeService> ctrl=like(true);try{FakeLikeService.callback.failed(0,"UNKNOWN_OUTCOME",false);Shadows.shadowOf(Looper.getMainLooper()).idleFor(Duration.ofSeconds(70));assertEquals(1,FakeLikeService.submits);assertFalse(new Library(c).find("sc:1").liked);assertTrue(Shadows.shadowOf(nm).getNotification(9).extras.getCharSequence(Notification.EXTRA_TEXT).toString().contains("неизвестен"));}finally{ctrl.destroy();}}
 @Test public void duplicateTapWhileBusyDoesNotSubmitTwice()throws Exception{ServiceController<FakeLikeService> ctrl=like(true);try{ctrl.get().onStartCommand(NotificationLikeService.command(c,track("1",false),true),0,2);assertEquals(1,FakeLikeService.submits);confirmed();}finally{ctrl.destroy();}}
 @Test public void changedAccountRejectsResult()throws Exception{ServiceController<FakeLikeService> ctrl=like(true);try{c.getSharedPreferences("profile",0).edit().putString("id","999").commit();confirmed();assertFalse(new Library(c).find("sc:1").liked);}finally{ctrl.destroy();}}
 @Test public void delayedConfirmationCannotResurrectDismissedCard()throws Exception{ServiceController<FakeLikeService> ctrl=like(true);try{new PlaybackNoticeReceiver().onReceive(c,new Intent("CLOSE").putExtra("owner","123"));confirmed();assertTrue(new Library(c).find("sc:1").liked);assertNull(Shadows.shadowOf(nm).getNotification(7));}finally{ctrl.destroy();}}
 @Test public void staleNotificationOwnerIsRejectedBeforeSending()throws Exception{ServiceController<FakeLikeService> ctrl=Robolectric.buildService(FakeLikeService.class).create();try{Intent command=NotificationLikeService.command(c,track("1",false),true).putExtra("owner","999");ctrl.get().onStartCommand(command,0,1);assertEquals(0,FakeLikeService.submits);assertTrue(Shadows.shadowOf(ctrl.get()).isStoppedBySelf());}finally{ctrl.destroy();}}
 @Test public void notificationServiceDoesNotStartResidentChecks()throws Exception{assertFalse(ResidentChecks.running());ServiceController<FakeLikeService> ctrl=like(true);try{assertFalse(ResidentChecks.running());confirmed();assertFalse(ResidentChecks.running());}finally{ctrl.destroy();}}
 @Test public void transportStopKeepsSelectedTrackAndForegroundCard()throws Exception{ServiceController<PlaybackService> ctrl=player();try{assertEquals(android.app.Service.START_STICKY,ctrl.get().onStartCommand(new Intent("STOP"),0,1));assertFalse(Shadows.shadowOf(ctrl.get()).isStoppedBySelf());assertNotNull(Shadows.shadowOf(nm).getNotification(7));assertEquals("sc:1",PlaybackCheckpoint.read(c).current());assertFalse(PlaybackCheckpoint.read(c).wanted);}finally{ctrl.destroy();}}

}
